import React, {useEffect} from 'react'
import './App.css';
import {BrowserRouter as Router, Switch, Route, Redirect, matchPath} from "react-router-dom";
import professorList from './json/professorsList.json'
import ReactGA from 'react-ga';
//Pages
import Home from './pages/Home.js'
import Professor from "./pages/Professor";
import useProfessor from "./hooks/useProfessor";
import {ApiMail} from "./api";


//hooks
function App() {
    useEffect(() => {
        ReactGA.initialize('G-PJ4SZRTXQV');
        //to report page view
        ReactGA.pageview('/')
    }, [])
    return (
        <Router>
            <Switch>
                <Route path='/' exact component={() => <Home professorList={professorList} />}/>
                <Route path="/professors/:endpoint" exact component={() => <Professor professorList={professorList} />} />
            </Switch>
        </Router>

);
}

export default App;
